// 当前页数
let currentPage = 1;

// 最大页数（根据实际存在的页面数量设置）
const maxPage = 2;

// 加载指定页码的内容
function loadPage(page) {
    if (page < 1 || page > maxPage) {
        console.error('Invalid page number:', page);
        return;
    }

    fetch(`HOME/${page}.html`)
        .then(response => {
            if (!response.ok) {
                throw new Error('Network response was not ok');
            }
            return response.text();
        })
        .then(data => {
            document.getElementById('blog-content').innerHTML = data;
        })
        .catch(error => {
            console.error('Error fetching the page:', error);
        });
}

// 初始化加载第一页
document.addEventListener('DOMContentLoaded', () => {
    loadPage(currentPage);
});

// 上一页按钮点击事件
document.getElementById('prev-page').addEventListener('click', () => {
    if (currentPage > 1) {
        currentPage--;
        loadPage(currentPage);
    }
});

// 下一页按钮点击事件
document.getElementById('next-page').addEventListener('click', () => {
    if (currentPage < maxPage) {
        currentPage++;
        loadPage(currentPage);
    }
});

/* styles.css */

/* 设置 body 元素的样式 */
body {
    background: linear-gradient(to right, #d3d3d3, #a9a9a9); /* 背景颜色设置为从左到右的渐变灰色 */
    font-family: Arial, sans-serif; /* 设置字体为 Arial，如果 Arial 不可用则使用 sans-serif */
    color: #333; /* 设置文本颜色为深灰色 */
    transition: background 0.5s; /* 背景颜色变化时添加0.5秒的过渡效果 */
    min-height: 100vh; /* 最小高度设置为100%的视口高度，确保页面至少填满整个屏幕 */
    display: flex; /* 使用弹性布局 */
    flex-direction: column; /* 弹性布局的方向设置为纵向 */
}

/* 设置 header 元素的样式 */
header {
    background: linear-gradient(to right, #1e3c72, #2a5298); /* 背景颜色设置为从左到右的渐变深蓝色 */
    color: white; /* 设置文本颜色为白色 */
}

/* 设置 footer 元素的样式 */
footer {
    background: linear-gradient(to right, #1e3c72, #2a5298); /* 背景颜色设置为从左到右的渐变深蓝色 */
    color: white; /* 设置文本颜色为白色 */
    text-align: center; /* 文本居中对齐 */
    padding: 1rem 0; /* 上下内边距设置为1rem，左右内边距为0 */
    margin-top: auto; /* 确保页脚位于页面最下端 */
}

/* 设置 h1, h2, h3 元素的样式 */
h1, h2, h3 {
    font-family: 'Georgia', serif; /* 设置字体为 Georgia，如果 Georgia 不可用则使用 serif */
    transition: color 0.3s; /* 颜色变化时添加0.3秒的过渡效果 */
}

/* 设置 h1, h2, h3 元素在悬停时的样式 */
h1:hover, h2:hover, h3:hover {
    color: #feb47b; /* 悬停时文本颜色变为淡橙色 */
}

/* 设置 p 元素的样式 */
p {
    transition: color 0.3s, transform 0.3s; /* 颜色和变换时添加0.3秒的过渡效果 */
}

/* 设置 p 元素在悬停时的样式 */
p:hover {
    color: #1e3c72; /* 悬停时文本颜色变为深蓝色 */
    transform: scale(1.05); /* 悬停时元素缩放至原来的1.05倍 */
}

/* 设置 li 元素的样式 */
li {
    transition: color 0.3s, transform 0.3s; /* 颜色和变换时添加0.3秒的过渡效果 */
}

/* 设置 li 元素在悬停时的样式 */
li:hover {
    color: #1e3c72; /* 悬停时文本颜色变为深蓝色 */
    transform: scale(1.05); /* 悬停时元素缩放至原来的1.05倍 */
}

/* 设置 article 元素的样式 */
article {
    margin-bottom: 2rem; /* 底部外边距设置为2rem */
}

/* 设置 aside 元素的样式 */
aside {
    background: linear-gradient(to right, #f0f0f0, #e0e0e0); /* 背景颜色设置为从左到右的渐变浅灰色 */
    padding: 1rem; /* 内边距设置为1rem */
    border-radius: 5px; /* 设置圆角半径为5px */
    transition: background 0.3s, transform 0.3s; /* 背景颜色和变换时添加0.3秒的过渡效果 */
}

/* 设置 aside 元素在悬停时的样式 */
aside:hover {
    background: linear-gradient(to right, #e0e0e0, #d0d0d0); /* 悬停时背景颜色变为从左到右的渐变灰色 */
    transform: scale(1.05); /* 悬停时元素缩放至原来的1.05倍 */
}

/* 设置导航栏（navbar）元素的样式 */
.navbar {
    background: linear-gradient(to right, #d3d3d3, #a9a9a9); /* 背景颜色设置为从左到右的渐变灰色 */
    transition: background 0.5s; /* 背景颜色变化时添加0.5秒的过渡效果 */
}

/* 设置导航链接（nav-link）元素的样式 */
.nav-link {
    color: #333; /* 设置文本颜色为深灰色 */
    transition: color 0.3s, transform 0.3s; /* 颜色和变换时添加0.3秒的过渡效果 */
}

/* 设置导航链接（nav-link）元素在悬停时的样式 */
.nav-link:hover {
    color: #1e3c72; /* 悬停时文本颜色变为深蓝色 */
    transform: scale(1.05); /* 悬停时元素缩放至原来的1.05倍 */
}

/* 设置分页容器的样式 */
.pagination-container {
    text-align: center; /* 文本居中对齐 */
    margin-top: 2rem; /* 顶部外边距设置为2rem */
}

/* 设置分页按钮的样式 */
.pagination-button {
    background-color: #333; /* 按钮背景颜色设置为深灰色 */
    color: white; /* 按钮文本颜色设置为白色 */
    border: none; /* 移除按钮边框 */
    padding: 0.5rem 1rem; /* 按钮内边距设置为上下0.5rem，左右1rem */
    margin: 0 0.5rem; /* 按钮外边距设置为左右0.5rem */
    border-radius: 5px; /* 按钮圆角半径设置为5px */
    cursor: pointer; /* 鼠标悬停时显示为指针 */
    transition: background-color 0.3s, transform 0.3s; /* 背景颜色和变换时添加0.3秒的过渡效果 */
}

/* 设置分页按钮在悬停时的样式 */
.pagination-button:hover {
    background-color: #1e3c72; /* 悬停时背景颜色变为深蓝色 */
    transform: scale(1.1); /* 悬停时按钮缩放至原来的1.1倍 */
}

/* 设置容器、导航栏、页眉和页脚元素的过渡效果 */
.container, .navbar, header, footer {
    transition: background 0.5s, color 0.5s; /* 背景颜色和文本颜色变化时添加0.5秒的过渡效果 */
}
